/**
 * The regular lanes of the synteny RPC payload: parallel typed arrays plus
 * dictionary-encoded string lanes (a `<name>Dict`/`<name>Ids` pair each — see
 * `StringDict` for why per-feature strings ship this way). Emitted from
 * `SYNTENY_LANES`; the irregular payload fields stay on the hand-written
 * `SyntenyFeatureData`, which extends this.
 */
export interface SyntenyFeatureLanes {
  /**
   * Alignment strand, +1 or -1 — the relative orientation of the two axes, so
   * `followAxes` swaps it in neither direction.
   */
  strands: Int8Array
  /**
   * Chromosome-local feature start (not cumulative), so uint32 holds it as long
   * as no single reference sequence exceeds 2^32 bp — an assumption we accept
   * (agent-docs/ARCHITECTURE.md "Genome-size limits"). The feature-detail panel
   * and the min-length cull read these; drawn positions come from Float64 cumBp
   * arrays that never leave the worker (ADR-067).
   */
  starts: Uint32Array
  /**
   * Chromosome-local feature end; see `starts`.
   */
  ends: Uint32Array
  /**
   * Genuinely distinct per feature, so this one stays a `string[]`: a
   * dictionary of 500k distinct strings costs the same clone plus an index
   * array. See `makeStringDict`, which is also where the measurement lives.
   */
  featureIds: string[]
  /**
   * A gene symbol (an MCScan or ortholog-table row) or nothing at all — a PAF
   * names no features, and the packers write `UNNAMED` so "is this record
   * named" resolves through `unnamedNameId` rather than restating the
   * convention.
   */
  nameDict: string[]
  nameIds: Uint32Array
  /**
   * The contig on the query axis. The worker interns whatever spelling the file
   * uses; the main thread rewrites it into the query assembly's canonical
   * namespace, since every reader there (`dynamicBlocks`, `displayedRegions`,
   * `assembly.refNames`) is canonical.
   */
  refNameDict: string[]
  refNameIds: Uint32Array
  /**
   * The query row's assembly as the adapter spells it — deliberately NOT
   * canonicalized: it goes back OUT, as the `regions[]` assembly of
   * `SyntenyResolveMatchingRegion`, which the adapter matches against its own
   * `assemblyNames[]`, so canonicalizing it would break the lookup that works.
   */
  assemblyNameDict: string[]
  assemblyNameIds: Uint32Array
  /**
   * Mate start in the mate contig's own bp, uint32 like `starts`. There is no
   * mate name lane: `mate.name` was always undefined (no adapter sets it), so
   * it was dropped.
   */
  mateStarts: Uint32Array
  /**
   * Mate end; see `mateStarts`.
   */
  mateEnds: Uint32Array
  /**
   * The contig on the target axis — the new information a synteny feature
   * carries, about a region nobody requested. It arrives in the file's spelling
   * and is rewritten into the TARGET assembly's canonical namespace.
   */
  mateRefNameDict: string[]
  mateRefNameIds: Uint32Array
  /**
   * The mate's assembly: the adapter's `assemblyNames[]` config text, verbatim.
   * Canonicalized through `getCanonicalAssemblyName` because
   * `pickFollowFeature`, `followWindowMapping` and `centerOnFeature` compare it
   * against a view's `assemblyNames[0]`, which is canonical — a track declaring
   * its second assembly by an alias otherwise draws its ribbons while the
   * follow drops every candidate.
   */
  mateAssemblyNameDict: string[]
  mateAssemblyNameIds: Uint32Array
}
